entries[138640] = { ["name"] = "Knochenweißer Urraptor", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren knochenweißen Urraptor und gibt ihn wieder frei.\n\"Mit acht Monaten sind sie tödlich, äußerst tödlich.\" - Hemet Nesingwary Jr.\nQuest:\nEin Berg riesiger Dinosaurierknochen\nZone:\nInsel der Riesen" }
entries[138641] = { ["name"] = "Roter Urraptor", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren roten Urraptor und gibt ihn wieder frei.\n\"Raptoren haben sich in praktisch allen Landen von Azeroth verbreitet. Es ist unklar, ob die Trolle sie hergeführt haben oder sie ihnen gefolgt sind.\"\nBeute von:\nZerbrochene Ureischale" }
entries[138642] = { ["name"] = "Schwarzer Urraptor", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren schwarzen Urraptor und gibt ihn wieder frei.\n\"Geschwindigkeit, Gerissenheit und Wildheit sind Dinge, die Trolle und Raptoren aneinander bewundern.\"\nBeute von:\nZerbrochene Ureischale" }
entries[138643] = { ["name"] = "Grüner Urraptor", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren grünen Urraptor und gibt ihn wieder frei.\n\"Raptoren sind genauso treu, wie sie bösartig sind. Wenn Ihr kein Freund seid, seid Ihr eine Mahlzeit.\" - Kijara\nBeute von:\nZerbrochene Ureischale" }
